-- execution plans, one file per sql_id. An aged-out cursor makes DISPLAY_CURSOR
-- print "cannot be found"; the block then tries the AWR repository. Failures are
-- caught per sql_id, so one missing plan does not stop the others.
set markup csv off
set serveroutput on size unlimited format wrapped
set linesize 1000 pagesize 0 heading off tab off

spool ref/plans/0123456789abc.txt
declare
  l_n    pls_integer := 0;
  l_miss boolean := false;
begin
  for r in (select plan_table_output p from table(dbms_xplan.display_cursor('0123456789abc', null, 'ALLSTATS LAST +PREDICATE +ALIAS'))) loop
    if l_n = 0 and r.p like '%cannot be found%' then l_miss := true; exit; end if;
    l_n := l_n + 1;
    dbms_output.put_line(r.p);
  end loop;
  if l_miss or l_n = 0 then
    for r in (select plan_table_output p from table(dbms_xplan.display_awr('0123456789abc', null, null, 'TYPICAL +PREDICATE +ALIAS'))) loop
      l_n := l_n + 1;
      dbms_output.put_line(r.p);
    end loop;
  end if;
  if l_n = 0 then dbms_output.put_line('-- no plan found for 0123456789abc'); end if;
exception when others then
  dbms_output.put_line('-- no plan for 0123456789abc: ' || sqlerrm);
end;
/
spool off

spool ref/plans/abcdefghijklm.txt
declare
  l_n    pls_integer := 0;
  l_miss boolean := false;
begin
  for r in (select plan_table_output p from table(dbms_xplan.display_cursor('abcdefghijklm', null, 'ALLSTATS LAST +PREDICATE +ALIAS'))) loop
    if l_n = 0 and r.p like '%cannot be found%' then l_miss := true; exit; end if;
    l_n := l_n + 1;
    dbms_output.put_line(r.p);
  end loop;
  if l_miss or l_n = 0 then
    for r in (select plan_table_output p from table(dbms_xplan.display_awr('abcdefghijklm', null, null, 'TYPICAL +PREDICATE +ALIAS'))) loop
      l_n := l_n + 1;
      dbms_output.put_line(r.p);
    end loop;
  end if;
  if l_n = 0 then dbms_output.put_line('-- no plan found for abcdefghijklm'); end if;
exception when others then
  dbms_output.put_line('-- no plan for abcdefghijklm: ' || sqlerrm);
end;
/
spool off

exit
